6	// Transient gateway failures worth one attempt on the fallback base URL.
7	// 500/429 included: the gateway intermittently 500s large codegen calls and
8	// rate-limits bursts — a single retry saves the whole job.
9	const retryableStatus = new Set<number>([404, 405, 429, 500, 502, 503, 504]);
10	
11	// Word-boundaried: must not match inside larger numbers (e.g. a JSON
12	// parse error reporting "position 25029" contains "502" — not a 502).
13	const TRANSIENT_RE = /(\b500\b|\b502\b|\b503\b|\b504\b|\b429\b|fetch failed|timeout|ECONNRESET)/i;
14	
15	const baseUrlCandidates = (): string[] => {
16	  const urls = [config.baseUrl];
17	  if (config.fallbackBaseUrl && config.fallbackBaseUrl !== config.baseUrl) {
18	    urls.push(config.fallbackBaseUrl);
19	  }
20	  return urls;
21	};
22	
23	type ErrorBody = { error?: { message?: string }; message?: string };
24	
25	const readErrorBody = async (response: Response): Promise<string> => {
26	  const text = await response.text();
27	  try {
28	    const json = JSON.parse(text) as ErrorBody;
29	    return json.error?.message || json.message || text;
30	  } catch {
31	    return text.slice(0, 600);
32	  }
33	};
34	
35	type PostJsonOptions = { expectBinary?: boolean };
36	
37	// Overloads keep the binary (speech) call typed as Buffer and the JSON call
38	// typed as the caller's response shape, without leaking `any` at call sites.
39	function postJson<T>(
40	  path: string,
41	  body: unknown,
42	  options?: { expectBinary?: false },
43	): Promise<T>;
44	function postJson(
45	  path: string,
46	  body: unknown,
47	  options: { expectBinary: true },
48	): Promise<Buffer>;
49	async function postJson(
50	  path: string,
51	  body: unknown,
52	  { expectBinary = false }: PostJsonOptions = {},
53	): Promise<unknown> {
54	  if (!config.apiKey) {
55	    throw new Error('Missing AICREDITS_API_KEY in .env.');
56	  }
57	
58	  const bodyRecord = (body ?? {}) as { model?: string; voice?: string };
59	  let lastError: unknown = null;
60	
61	  for (const baseUrl of baseUrlCandidates()) {
62	    try {
63	      const response = await fetch(`${baseUrl}${path}`, {
64	        method: 'POST',
65	        headers: {
66	          Authorization: `Bearer ${config.apiKey}`,
67	          'Content-Type': 'application/json',
68	        },
69	        body: JSON.stringify(body),
70	      });
71	
72	      if (!response.ok) {
73	        const message = await readErrorBody(response);
74	        const error = new ApiError(
75	          `AICredits ${response.status} from ${baseUrl}${path} (model=${bodyRecord.model || 'n/a'} voice=${bodyRecord.voice || 'n/a'}): ${message}`,
76	          {
77	            status: response.status,
78	            detail: {
79	              baseUrl,
80	              path,
81	              model: bodyRecord.model,
82	              voice: bodyRecord.voice,
83	            },
84	          },
85	        );
86	        lastError = error;
87	
88	        if (retryableStatus.has(response.status)) {
89	          continue;
90	        }
91	
92	        throw error;
93	      }
94	
95	      if (expectBinary) {
96	        return Buffer.from(await response.arrayBuffer());
97	      }
98	
99	      return response.json();
100	    } catch (error) {
101	      lastError = error;
102	      const message = error instanceof Error ? error.message : String(error);
103	      if (!message.includes('fetch failed')) {
104	        throw error;
105	      }
106	    }
107	  }
108	
109	  throw lastError ?? new Error(`AICredits request failed for ${path}.`);
110	}
