138	// Known-invalid voices that users commonly set: OpenAI voices and
139	// legacy Sarvam names. Kept for a clearer warning message.
140	const KNOWN_INVALID_FOR_BULBUL = new Set<string>([
141	  'alloy', 'echo', 'fable', 'onyx', 'nova', 'shimmer',
142	  'meera', 'diya',
143	]);
