145	const detectBulbulVersion = (model?: string): BulbulVersion => {
146	  const normalized = String(model || '').toLowerCase();
147	  if (normalized.includes('v3')) return 'v3';
148	  if (normalized.includes('v2')) return 'v2';
149	  return 'v3';
150	};
151	
152	export const OPENAI_TTS_VOICES = new Set<string>(['alloy', 'echo', 'fable', 'onyx', 'nova', 'shimmer']);
153	
154	export type ResolvedVoice = {
155	  voice: string;
156	  version: 'openai' | BulbulVersion;
157	  fallbackUsed: boolean;
158	};
159	
160	export const resolveSpeechVoice = (model: string, voice: string): ResolvedVoice => {
161	  const requested = String(voice || '').trim().toLowerCase();
162	
163	  if (String(model || '').toLowerCase().startsWith('openai/')) {
164	    if (OPENAI_TTS_VOICES.has(requested)) {
165	      return { voice: requested, version: 'openai', fallbackUsed: false };
166	    }
167	    console.warn(`[speech] Voice '${requested}' is not valid for ${model}; falling back to 'alloy'.`);
168	    return { voice: 'alloy', version: 'openai', fallbackUsed: true };
169	  }
170	
171	  const version = detectBulbulVersion(model);
172	  const allowed = version === 'v2' ? BULBUL_V2_SPEAKERS : BULBUL_V3_SPEAKERS;
173	  const fallback = DEFAULT_VOICE_BY_MODEL[version];
174	
175	  if (allowed.has(requested)) {
176	    return { voice: requested, version, fallbackUsed: false };
177	  }
178	
179	  if (requested && (KNOWN_INVALID_FOR_BULBUL.has(requested) || requested)) {
180	    console.warn(
181	      `[speech] Speaker '${requested}' is not valid for bulbul:${version}; falling back to '${fallback}'.`,
182	    );
183	  }
184	
185	  return { voice: fallback, version, fallbackUsed: true };
186	};
