188	const extractJson = (content: string): Record<string, unknown> => {
189	  const fenced = content.match(/```(?:json)?\s*([\s\S]*?)```/i);
190	  const candidate = fenced ? fenced[1] : content;
191	  const start = candidate.indexOf('{');
192	  const end = candidate.lastIndexOf('}');
193	
194	  if (start === -1 || end === -1 || end <= start) {
195	    throw new Error('Model did not return a JSON object.');
196	  }
197	
198	  return JSON.parse(candidate.slice(start, end + 1)) as Record<string, unknown>;
199	};
