264	export const detectThemeFromPrompt = (prompt: string): ReelTheme => {
265	  const p = prompt.toLowerCase();
266	  if (/(?:funny|comedy|joke|meme|laugh|hilarious|satire|fun|roast|humor)/i.test(p)) return 'comedy';
267	  if (/(?:money|finance|stock|invest|crypto|wealth|market|profit|revenue|dollar|cash|trading|economy)/i.test(p)) return 'finance';
268	  if (/(?:story|journey|character|once upon|dramatic|legend|historical|biography|tale|narrative|anime|titan|eren|mikasa|love story|tragic|romance|cinematic)/i.test(p)) return 'storytelling';
269	  if (/(?:health|fitness|workout|wellness|lifestyle|travel|food|cooking|mindfulness|diet|meditation)/i.test(p)) return 'lifestyle';
270	  if (/(?:tech|ai|code|software|model|computer|algorithm|hardware|cloud|data|app|neural|developer|gemini|robot)/i.test(p)) return 'tech';
271	  return 'education';
272	};
