274	export const extractUserColors = (prompt: string): string[] => {
275	  const p = prompt.toLowerCase();
276	  const colors: string[] = [];
277	  if (/\b(?:yellow|gold|amber)\b/.test(p)) colors.push('#FFE600');
278	  if (/\b(?:neon|lime|green|emerald)\b/.test(p)) colors.push('#E0FE10', '#00FF66');
279	  if (/\b(?:cyan|electric blue|aqua)\b/.test(p)) colors.push('#00F5FF');
