308	const normalizeScene = (scene: unknown, index: number, theme: ReelTheme): Scene => {
309	  const raw = (scene ?? {}) as RawScene;
310	  const rawVisual = String(raw.visual || '').trim() as Visual;
311	  const rawHasImage = Boolean(raw.imageUrl || ((raw.visualData ?? {}) as Record<string, unknown>).imageUrl);
312	  const isStoryVisual =
313	    rawVisual === 'cinematic_character' ||
314	    rawVisual === 'character_duo' ||
315	    rawVisual === 'scarf_wind' ||
316	    rawVisual === 'water_breathing' ||
317	    rawVisual === 'hinokami_kagura' ||
318	    rawVisual === 'landscape_canvas';
319	
320	  // Topic-neutral rotation used when the model requests a photo-style
321	  // visual but no image is available. Deliberately generic — works for food,
322	  // health, finance, comedy, tech, and stories alike.
323	  const motionGraphicsFallbacks: Visual[] = [
324	    'kinetic_typography',
325	    'bento_grid',
326	    'stat_spotlight',
327	    'quote_card',
328	    'comparison_matrix',
329	    'timeline_path',
330	    'split_screen',
331	    'radial_gauge',
332	    'neural_flow',
333	  ];
334	
335	  let visual: Visual;
336	  if (!rawHasImage && isStoryVisual && theme !== 'storytelling') {
337	    visual = motionGraphicsFallbacks[index % motionGraphicsFallbacks.length];
338	  } else if (VISUALS.has(rawVisual)) {
339	    visual = rawVisual;
340	  } else {
341	    visual = FALLBACK_VISUALS[index % FALLBACK_VISUALS.length];
342	  }
343	
344	  const palette = THEME_PALETTES[theme] || THEME_PALETTES.education;
345	  const rawTransition = String(raw.transition || '').trim() as TransitionType;
346	  const transition: TransitionType | undefined = VALID_TRANSITIONS.has(rawTransition)
347	    ? rawTransition
348	    : undefined;
349	
350	  const rawVd = (raw.visualData ?? {}) as Record<string, unknown>;
351	  const rawElements = Array.isArray(rawVd.elements) ? rawVd.elements : [];
352	  const rawNodes = Array.isArray(rawVd.nodes) ? rawVd.nodes : [];
353	  const rawBars = Array.isArray(rawVd.bars) ? rawVd.bars : [];
354	  const rawHighlights = Array.isArray(rawVd.highlightWords) ? rawVd.highlightWords : [];
355	  const rawStickers = Array.isArray(rawVd.stickers) ? rawVd.stickers : [];
356	  const rawBubbles = Array.isArray(rawVd.speechBubbles) ? rawVd.speechBubbles : [];
357	
358	  const narrationBeat = raw.narrationBeat
359	    ? clampText(raw.narrationBeat, 240)
360	    : clampText(raw.body || raw.headline, 240);
361	
362	  return {
363	    kicker: clampText(raw.kicker || `Beat ${index + 1}`, 28),
364	    headline: clampText(raw.headline || 'Key idea', 64),
365	    body: clampText(raw.body || narrationBeat, 180),
366	    narrationBeat,
367	    visual,
368	    accent: isHex(raw.accent) ? String(raw.accent) : palette[(index + 1) % palette.length],
369	    durationWeight: Math.max(0.5, Math.min(3, Number(raw.durationWeight) || 1)),
370	    transition,
371	    visualData: {
372	      tag: rawVd.tag ? clampText(rawVd.tag, 32) : undefined,
373	      metric: rawVd.metric ? clampText(rawVd.metric, 24) : undefined,
