495	// Measured from openai/tts-1 (alloy) output: 2.42-2.64 words per second.
496	const WORDS_PER_SECOND = 2.5;
497	// jobs.ts adds this much silence after the voice.
498	export const TAIL_SECONDS = 0.6;
499	
500	// "20-second", "30 sec", "45s", "1 minute", "1.5 min". First match wins.
501	// Values outside 5-180s (the composition's clamp) are ignored, e.g. "1990s".
502	export const extractTargetSeconds = (prompt: string): number | null => {
503	  const match = String(prompt).match(/(\d+(?:\.\d+)?)\s*-?\s*(seconds?|secs?|s|minutes?|mins?)\b/i);
504	  if (!match) return null;
505	  const seconds = Number(match[1]) * (/^m/i.test(match[2]) ? 60 : 1);
506	  return seconds >= 5 && seconds <= 180 ? seconds : null;
507	};
508	
509	export const wordBudgetFor = (seconds: number): number =>
510	  Math.round((seconds - TAIL_SECONDS) * WORDS_PER_SECOND);
