581	  const raw = extractJson(content);
582	  const rawTheme = String(raw.theme || '').toLowerCase() as ReelTheme;
583	  const theme = THEMES.has(rawTheme) ? rawTheme : detectedTheme;
584	  const script = String(raw.script || prompt).trim();
585	
