766	export type GenerateVisualCodeOptions = {
767	  system: string;
768	  user: string;
769	};
770	
771	type VisualCodeResponse = { code?: unknown };
772	
773	export type VisualCodeResult = { code: string | null; error?: string };
774	
775	const isBalanceError = (message: string): boolean =>
776	  /402|insufficient balance|budget exceeded/i.test(message);
777	
778	/**
779	 * Execute one bespoke-visual codegen call. Retries ONCE on transient gateway
780	 * failures — but NEVER on an empty wallet: a 402 fails fast with a top-up
781	 * message instead of burning more attempts. Never throws; the reason travels
782	 * in `error` so jobs fail with the truth, not a generic message.
783	 */
784	export const generateVisualCode = async ({
785	  system,
786	  user,
787	}: GenerateVisualCodeOptions): Promise<VisualCodeResult> => {
788	  const body = {
789	    model: config.videoModel,
790	    messages: [
791	      { role: 'system', content: system },
792	      { role: 'user', content: user },
793	    ],
794	    temperature: 0.5,
795	    // Detailed multi-beat components are long — a low ceiling truncates the
796	    // JSON mid-code (fatal, unrecoverable). gpt-4.1-mini allows 32k output.
797	    max_tokens: 16000,
798	    response_format: { type: 'json_object' },
799	  };
800	  for (let attempt = 1; attempt <= 2; attempt += 1) {
801	    try {
802	      const response = await postJson<ChatCompletionResponse>('/chat/completions', body);
803	      const content = response.choices?.[0]?.message?.content;
804	      if (!content) return { code: null, error: 'empty response from model' };
805	      const raw = extractJson(content) as VisualCodeResponse;
806	      const code = String(raw.code || '').trim();
807	      if (code.length >= 200) return { code };
808	      console.warn('[codegen] LLM returned too little code — treating as failure.');
809	      return { code: null, error: 'model returned too little code' };
810	    } catch (error) {
811	      const message = error instanceof Error ? error.message : String(error);
812	      console.warn(`[codegen] LLM call failed (attempt ${attempt}/2): ${message.slice(0, 300)}.`);
813	      if (isBalanceError(message)) {
814	        return { code: null, error: 'AICredits balance exhausted — top up the account and resubmit (no further attempts will succeed until then)' };
815	      }
816	      if (attempt === 2 || !TRANSIENT_RE.test(message)) return { code: null, error: message.slice(0, 300) };
817	    }
818	  }
819	  return { code: null, error: 'unknown codegen failure' };
820	};
