830	    Math.max(15, Math.round(scriptData.script.split(/\s+/).length / WORDS_PER_SECOND));
831	
832	  const scenes = await choreographScenes({
833	    prompt,
834	    title: scriptData.title,
835	    theme: scriptData.theme,
836	    script: scriptData.script,
837	    speechSeconds: estimatedSeconds,
838	    researchContext,
839	  });
840	
841	  return {
842	    title: scriptData.title,
843	    theme: scriptData.theme,
844	    narration: scriptData.script,
845	    scenes,
846	    style: {
847	      theme: scriptData.theme,
848	      mood: scriptData.mood,
849	      palette: scriptData.palette,
