856	export type GenerateSpeechOptions = {
857	  text: string;
858	  outputPath: string;
859	  speed?: number;
860	};
861	
862	export const generateSpeech = async ({
863	  text,
864	  outputPath,
865	  speed = 1,
866	}: GenerateSpeechOptions): Promise<string> => {
867	  // Resolve through the allowlist so a stale .env value like
868	  // SPEECH_VOICE=alloy|meera|diya can't produce an AICredits 400.
869	  const { voice } = resolveSpeechVoice(config.speechModel, config.speechVoice);
870	
871	  const audio = await postJson(
872	    '/audio/speech',
873	    {
874	      model: config.speechModel,
875	      input: text,
876	      voice,
877	      response_format: config.speechFormat,
878	      ...(speed !== 1 ? { speed } : {}),
879	    },
880	    { expectBinary: true },
881	  );
882	
883	  if (audio.length < 1000) {
884	    throw new Error('Speech API returned an unexpectedly small audio file.');
885	  }
886	
887	  await fs.writeFile(outputPath, audio);
888	  return outputPath;
889	};
890	
891	type WhisperVerboseResponse = {
892	  text?: string;
893	  duration?: number;
894	  words?: Array<{ word?: string; start?: number; end?: number }>;
895	};
896	
897	/**
898	 * Transcribe our own TTS audio with word-level timestamps (Whisper
899	 * verbose_json). This is what makes scenes land on the words actually
900	 * spoken instead of on the LLM's guesses.
901	 *
902	 * Returns null on ANY failure (gateway has no transcription endpoint, model
903	 * rejected, network error, garbage output) — the caller falls back to
904	 * syllable-estimated timings and the reel still renders.
905	 */
906	export type TranscribeResult = { words: TranscriptWord[] | null; error?: string };
907	
908	export const transcribeWords = async (audioPath: string): Promise<TranscribeResult> => {
909	  try {
910	    if (!config.apiKey) return { words: null, error: 'missing API key' };
911	    const audio = await fs.readFile(audioPath);
912	    if (audio.length < 1000) return { words: null, error: 'audio file too small' };
913	
914	    for (const baseUrl of baseUrlCandidates()) {
915	      try {
916	        const form = new FormData();
917	        form.append('file', new Blob([audio], { type: 'audio/mpeg' }), 'narration.mp3');
918	        form.append('model', config.transcribeModel);
919	        form.append('response_format', 'verbose_json');
920	        form.append('timestamp_granularities[]', 'word');
921	
922	        const response = await fetch(`${baseUrl}/audio/transcriptions`, {
923	          method: 'POST',
924	          headers: { Authorization: `Bearer ${config.apiKey}` },
925	          body: form,
926	        });
927	        if (!response.ok) {
928	          if (retryableStatus.has(response.status)) continue;
929	          const err = `${response.status} from ${baseUrl}: ${(await readErrorBody(response)).slice(0, 200)}`;
930	          console.warn(`[transcribe] ${err}`);
931	          return { words: null, error: err };
932	        }
933	        const data = (await response.json()) as WhisperVerboseResponse;
934	        const words = (data.words || [])
935	          .filter((w) => typeof w.word === 'string' && w.word.trim().length > 0)
936	          .map((w) => ({
937	            word: String(w.word).trim(),
938	            start: Math.max(0, Number(w.start) || 0),
939	            end: Math.max(0, Number(w.end) || 0),
940	          }))
941	          .filter((w) => w.end >= w.start);
942	        if (words.length < 3) {
943	          // Most common cause: the gateway returns plain text with no word
944	          // timestamps (verbose_json granularity unsupported) — timing falls
945	          // back to syllabic estimates, which still keeps cuts on breaths.
946	          const hasText = typeof data.text === 'string' && data.text.trim().length > 0;
947	          const err = hasText
948	            ? 'transcript has text but no word timestamps (granularity unsupported)'
949	            : 'too few words returned';
950	          console.warn(`[transcribe] ${err}, ignoring.`);
951	          return { words: null, error: err };
952	        }
953	        return { words };
954	      } catch (error) {
955	        const message = error instanceof Error ? error.message : String(error);
956	        if (message.includes('fetch failed')) continue;
957	        console.warn(`[transcribe] failed: ${message.slice(0, 200)}`);
958	        return { words: null, error: message.slice(0, 200) };
959	      }
960	    }
961	    return { words: null, error: 'all transcription endpoints unreachable' };
962	  } catch (error) {
963	    const message = (error instanceof Error ? error.message : String(error)).slice(0, 200);
964	    console.warn(`[transcribe] failed: ${message}`);
965	    return { words: null, error: message };
966	  }
967	};
